package com.rohit.inventory.controller;
import com.rohit.inventory.dto.request.*; import com.rohit.inventory.dto.response.*; import com.rohit.inventory.entity.*; import com.rohit.inventory.service.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class MasterDataController { private final MasterDataService data; private final UserService users; public MasterDataController(MasterDataService data,UserService users){this.data=data;this.users=users;} private UUID actor(UserDetails u){return users.idForEmail(u.getUsername());}
@GetMapping("/warehouses") @PreAuthorize("hasAuthority('WAREHOUSE_READ')") public ApiResponse<Page<MasterDataResponse>> warehouses(@RequestParam(required=false)String search,@RequestParam(required=false)WarehouseStatus status,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable p){return ApiResponse.success("Warehouses retrieved successfully",data.warehouses(search,status,p));} @GetMapping("/warehouses/{id}") @PreAuthorize("hasAuthority('WAREHOUSE_READ')") public ApiResponse<MasterDataResponse> warehouse(@PathVariable UUID id){return ApiResponse.success("Warehouse retrieved successfully",data.warehouse(id));} @PostMapping("/warehouses") @PreAuthorize("hasAuthority('WAREHOUSE_CREATE')") public ApiResponse<MasterDataResponse> createWh(@Valid @RequestBody WarehouseRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Warehouse created successfully",data.warehouse(r,actor(u),null));} @PutMapping("/warehouses/{id}") @PreAuthorize("hasAuthority('WAREHOUSE_UPDATE')") public ApiResponse<MasterDataResponse> updateWh(@PathVariable UUID id,@Valid @RequestBody WarehouseRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Warehouse updated successfully",data.warehouse(r,actor(u),id));} @PatchMapping("/warehouses/{id}/status") @PreAuthorize("hasAuthority('WAREHOUSE_UPDATE')") public ApiResponse<MasterDataResponse> statusWh(@PathVariable UUID id,@RequestParam WarehouseStatus status,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Warehouse status updated successfully",data.warehouseStatus(id,status,actor(u)));}
@GetMapping("/warehouses/{id}/zones") @PreAuthorize("hasAuthority('WAREHOUSE_READ')") public ApiResponse<List<MasterDataResponse>> zones(@PathVariable UUID id){return ApiResponse.success("Zones retrieved successfully",data.zoneList(id));} @PostMapping("/warehouses/{id}/zones") @PreAuthorize("hasAuthority('WAREHOUSE_UPDATE')") public ApiResponse<MasterDataResponse> zone(@PathVariable UUID id,@Valid @RequestBody ZoneRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Zone created successfully",data.zone(id,r,actor(u),null));}
@GetMapping("/products") @PreAuthorize("hasAuthority('PRODUCT_READ')") public ApiResponse<Page<MasterDataResponse>> products(@RequestParam(required=false)String search,@RequestParam(required=false)ProductStatus status,@RequestParam(required=false)UUID categoryId,@RequestParam(required=false)UUID supplierId,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable p){return ApiResponse.success("Products retrieved successfully",data.products(search,status,categoryId,supplierId,p));} @GetMapping("/products/{id}") @PreAuthorize("hasAuthority('PRODUCT_READ')") public ApiResponse<MasterDataResponse> product(@PathVariable UUID id){return ApiResponse.success("Product retrieved successfully",data.product(id));} @PostMapping("/products") @PreAuthorize("hasAuthority('PRODUCT_CREATE')") public ApiResponse<MasterDataResponse> product(@Valid @RequestBody ProductRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Product created successfully",data.product(r,actor(u),null));} @PutMapping("/products/{id}") @PreAuthorize("hasAuthority('PRODUCT_UPDATE')") public ApiResponse<MasterDataResponse> product(@PathVariable UUID id,@Valid @RequestBody ProductRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Product updated successfully",data.product(r,actor(u),id));} @PatchMapping("/products/{id}/status") @PreAuthorize("hasAuthority('PRODUCT_UPDATE')") public ApiResponse<MasterDataResponse> productStatus(@PathVariable UUID id,@RequestParam ProductStatus status,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Product status updated successfully",data.productStatus(id,status,actor(u)));}
@GetMapping("/categories") @PreAuthorize("hasAuthority('PRODUCT_READ')") public ApiResponse<List<MasterDataResponse>> categories(){return ApiResponse.success("Categories retrieved successfully",data.categories());} @PostMapping("/categories") @PreAuthorize("hasAuthority('PRODUCT_CREATE')") public ApiResponse<MasterDataResponse> category(@Valid @RequestBody CategoryRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Category created successfully",data.category(r,actor(u),null));} @PatchMapping("/categories/{id}/status") @PreAuthorize("hasAuthority('PRODUCT_UPDATE')") public ApiResponse<MasterDataResponse> categoryStatus(@PathVariable UUID id,@RequestParam ProductStatus status,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Category status updated successfully",data.categoryStatus(id,status,actor(u)));}
@GetMapping("/suppliers") @PreAuthorize("hasAuthority('PRODUCT_READ')") public ApiResponse<List<MasterDataResponse>> suppliers(){return ApiResponse.success("Suppliers retrieved successfully",data.suppliers());} @PostMapping("/suppliers") @PreAuthorize("hasAuthority('PRODUCT_CREATE')") public ApiResponse<MasterDataResponse> supplier(@Valid @RequestBody SupplierRequest r,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Supplier created successfully",data.supplier(r,actor(u),null));} @PatchMapping("/suppliers/{id}/status") @PreAuthorize("hasAuthority('PRODUCT_UPDATE')") public ApiResponse<MasterDataResponse> supplierStatus(@PathVariable UUID id,@RequestParam ProductStatus status,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Supplier status updated successfully",data.supplierStatus(id,status,actor(u)));} }
